
.wrapper {
  background: url("../assets/images/affiliate/bg.png") no-repeat center center;
  background-size: cover;
  background-attachment: fixed;

  .affiliate {
    max-width: 1550px;
    margin: 0 auto;
    min-height: 90vh;
    padding: 40px 0;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    .game-title {
      &.sub {
        font-size: 30px;
      }
    }
    .description {
      margin: 50px;
      display: flex;
      gap: 50px;
      .desc {
        display: flex;
        align-items: center;
        justify-content: center;
        color: #ffffff;
        gap: 10px;
        img {
          width: 50px;
        }
      }
    }
    .buttons {
      display: flex;
      flex-direction: column;
      gap: 20px;
       width: 200px;
    }
    .steps {
      background: #212534;
      padding: 40px;
      border-radius: 20px;
      width: 95%;
      margin: 50px auto;
      max-width: 1200px;
      display: flex;
      justify-content: space-between;
      flex-direction: column;
       max-width: 260px;
       gap: 10px;
      .step {
        display: flex;
        color: #ffffff;
        gap: 10px;
        justify-content: flex-start;
        align-items: center;
      }
    }
    .information {
      max-width: 1200px;
      width: 90%; margin: 0 auto;
      text-align: left;
      .game-title {
        text-align: left;
        margin: unset;
      }
      p {
        font-size: 16px;
        color: #ffffff;
      }
      ol {
        color: #ffffff;
        text-align: left;
        margin: 0;
        padding-left: 15px;
      }
      .terms {
        color: #ffffff;
        text-align: left;
        margin: 0;
        padding-left: 15px;
      }
      .table {
        :deep(.ant-table .ant-table-thead > tr > th) {
          text-align: center;
        }
        :deep(.ant-table .ant-table-thead > tr > th:nth-child(odd)),
        :deep(.ant-table .ant-table-tbody > tr > td:nth-child(odd)) {
          background: #303450;
        }
      }
      .boxes {
        display: flex;
        justify-content: center;
        align-items: center;
        flex-direction: column;
        gap: 40px;
        .box {
          flex: 1;
          background-color: #2b2b4b;
          padding: 20px;
          color: #ffffff;
          .bx-table {
            display: flex;
            justify-content: space-between;
          }
        }
      }
    }
  }
}
@media (max-width: 768px) {
  .wrapper {
    .affiliate {
      .description {
        flex-direction: column-reverse;
      }
      .information {
        .boxes {
          flex-direction: column;
        }
      }
      .steps {
        flex-direction: column;
        justify-content: flex-start;
        gap: 20px;
        max-width: 260px;
        .step {
        }
      }
    }
  }
}
